void header(const CommonStore& common,const StableId& id,const char* kind){const auto* h=common.state().facts.find(id);if(!h||h->domain!="military"||h->kind!=kind)fail("MilitaryDutySourceHeaderRequired",id);}
bool same_binding(const DutyExecutionBinding& a,const DutyExecutionBinding& b){if(a.index()!=b.index())return false;return std::visit([&](const auto& x){using T=std::decay_t<decltype(x)>;const auto& y=std::get<T>(b);if constexpr(std::is_same_v<T,DutyTravelAction>)return x.action_id==y.action_id&&x.journey_ref==y.journey_ref;else if constexpr(std::is_same_v<T,DutyStationAction>)return x.action_id==y.action_id;else return x.activity_ref==y.activity_ref&&x.activity_schema_version==y.activity_schema_version;},a);}
bool same_window(const DutyServiceWindowRef& a,const DutyServiceWindowRef& b,ExactArithmeticBudget budget){return a.duty_action_id==b.duty_action_id&&a.service_epoch==b.service_epoch&&a.ordinal==b.ordinal&&same_moment(a.opened_at,b.opened_at,budget)&&same_moment(a.planned_close_at,b.planned_close_at,budget);}
void collect(MilitaryDutyPeriodFact2& f,const MilitaryDutyQualification& q){for(const auto& p:q.actual_participant_refs)if(std::none_of(f.actual_participant_refs.begin(),f.actual_participant_refs.end(),[&](const auto& old){return old.actor_id==p.actor_id&&old.owner_activity_id==p.owner_activity_id&&old.occupation_source_id==p.occupation_source_id&&old.occupation_version==p.occupation_version;}))f.actual_participant_refs.push_back(p);append(f.route_or_station_source_refs,q.route_or_station_sources);append(f.participant_basis_refs,q.participant_basis_refs);append(f.supply_fact_refs,q.supply_sources);append(f.encounter_result_refs,q.encounter_result_refs);append(f.unresolved_conflict_refs,q.unresolved_conflict_refs);}
