Outcome<const MilitaryDutyPeriodFact2*> read_military_duty_period(const CommonStore& common,const MilitaryDutyState& state,const MilitaryDutyContext& c,const SourceRef& source,Integer schema){return guard<const MilitaryDutyPeriodFact2*>([&]{if(source.domain!="military"||source.kind!="military_duty_period"||schema!=2)fail("MilitaryDutyPeriod2SourceRequired",source.id);const auto* result=state.period_facts.find(source.id);if(!result)fail("MilitaryDutyPeriodSourceRequired",source.id);const MilitaryDutyWindowState* owner=nullptr;for(const auto& row:state.windows.rows())if(const auto* closed=std::get_if<DutyWindowClosed>(&row.second.state))if(closed->result_ref==source.id){if(owner)fail("DuplicateMilitaryDutyPeriodOwner",source.id);owner=&row.second;}if(!owner)fail("MilitaryDutyPeriodWindowRequired",source.id);check_window(common,state,c,*owner,take(c.stamps.read_current_moment()));return result;});}
Status validate_military_duty_sources(const CommonStore& common,const MilitaryDutyState& state,const MilitaryDutyContext& c,const WorldMoment& now){return status([&]{
 // Native selection is explicit; zero retains only the old generic contract.
 // A selected /4 requires its real original issuer even for an empty table.
 if(c.selected_dynamic_military==4&&(!c.assignments||!c.assignments->bound_to(common,state,c.catalog)))fail("MilitaryDutyAssignmentOriginalSourcesRequired");
 if(c.selected_dynamic_military==4&&(!c.condition_sources||&c.condition_sources->common!=&common))fail("MilitaryDutyConditionSourcesRequired");
 take(validate_military_duty_selected_layout(state,c.selected_dynamic_military?c.selected_dynamic_military:3));
 for(const auto& fact:common.state().facts.rows())if(fact.second.domain=="military"&&fact.second.kind=="military_duty_assignment"){
  if(c.selected_dynamic_military!=4||fact.first!=fact.second.id||!state.assignments.find(fact.first))fail("MilitaryDutyAssignmentHeaderWithoutSource",fact.first);
 }
 for(const auto& row:state.assignments.rows()){
  const SourceRef source{"military","military_duty_assignment",row.first};
  const auto associated=take(read_military_duty_assignment_association(common,state,source,1,c.selected_dynamic_military));
  if(associated.assignment!=&row.second||take(compare_world_moments(row.second.issued_at,now,c.budget))>0)fail("MilitaryDutyAssignmentIdentityMismatch",row.first);
  const auto* actual=take(c.assignments->read_assignment(source,1));
  if(actual!=&row.second)fail("MilitaryDutyAssignmentOriginalOwnerMismatch",row.first);
 }
 take(validate_military_duty_catalog(c.catalog));take(validate_military_duty_execution_bindings(common,state,c,now));std::set<StableId> accepted_ids,window_ids,result_ids,station_ids,terminal_ids;std::set<std::tuple<StableId,Integer,Integer>> window_keys;NativeMilitaryStationActionTimeRead station_read(common,state,c);for(const auto& row:state.terms.rows()){const auto& t=row.second;const auto* e=state.executions.find(row.first);const auto* accepted=e?state.accepted_sources.find(e->accepted_source_ref):nullptr;const auto& r=rule(c,t);if(row.first!=t.duty_action_id||!e||e->duty_action_id!=t.duty_action_id||!accepted||accepted->duty_action_id!=t.duty_action_id||!accepted_ids.insert(accepted->id).second||t.start_tick!=accepted->accepted_at.half_day_tick||t.start_tick<0||t.until_tick<=t.start_tick||t.until_tick-t.start_tick>r.maximum_authorization_half_days||take(compare_world_moments(accepted->accepted_at,now,c.budget))>0||e->service_epoch<0||e->next_period_ordinal<0)fail("MilitaryDutyExecutionSourceMismatch",row.first);header(common,accepted->id,"military_duty_terms");take(c.original.validate_accepted_terms(t,*accepted));if(e->current_window_ref){const auto* w=state.windows.find(*e->current_window_ref);if(!w||!std::holds_alternative<DutyWindowOpen>(w->state)||w->window.duty_action_id!=t.duty_action_id||w->window.service_epoch!=e->service_epoch)fail("MilitaryDutyCurrentWindowRequired",row.first);}if(e->last_result_ref){const auto* f=state.period_facts.find(*e->last_result_ref);if(!f||f->window.duty_action_id!=t.duty_action_id)fail("MilitaryDutyLastResultRequired",row.first);}Integer count=0;WorldMoment previous=accepted->accepted_at;for(const auto& entry:state.windows.rows())if(entry.second.window.duty_action_id==t.duty_action_id){const auto& w=entry.second;if(entry.first!=w.id||w.window.ordinal!=count++||w.window.service_epoch>e->service_epoch||take(compare_world_moments(w.window.opened_at,previous,c.budget))<0||!window_keys.emplace(t.duty_action_id,w.window.service_epoch,w.window.ordinal).second)fail("MilitaryDutyWindowOrderMismatch",w.id);check_window(common,state,c,w,now);window_ids.insert(w.id);if(const auto* closed=std::get_if<DutyWindowClosed>(&w.state)){if(!result_ids.insert(closed->result_ref).second)fail("DuplicateMilitaryDutyPeriodOwner",w.id);}previous=w.last_accounted_at;}if(count!=e->next_period_ordinal)fail("MilitaryDutyMissingWindow",t.duty_action_id);if(const auto* s=station(state,t.duty_action_id)){station_ids.insert(s->id);take(station_read.read_action_time_owner(military_station_action_time_registration(),s->actual_action.id));if(const auto* end=terminal(state,s->id))terminal_ids.insert(end->id);else if(take(compare_world_moments(now,until(t,c.budget),c.budget))>=0)fail("MilitaryStationUnconsumedExpiry",s->id);}else if(t.execution_binding&&std::holds_alternative<DutyStationAction>(*t.execution_binding))fail("MilitaryStationSourceRequired",t.duty_action_id);if(t.state==MilitaryDutyPhase::active&&!e->current_window_ref)fail("MilitaryDutyActiveWindowRequired",t.duty_action_id);}
for(const auto& row:state.controls.rows()){const auto& control=row.second;const auto& t=terms(state,control.duty_action_id);if(row.first!=control.id||take(compare_world_moments(control.occurred_at,now,c.budget))>0)fail("MilitaryDutyControlSourceMismatch",row.first);header(common,control.id,"military_duty_control");take(c.original.validate_control_history(t,control));}if(state.executions.rows().size()!=state.terms.rows().size()||accepted_ids.size()!=state.accepted_sources.rows().size()||window_ids.size()!=state.windows.rows().size()||result_ids.size()!=state.period_facts.rows().size()||station_ids.size()!=state.station_sources.rows().size()||terminal_ids.size()!=state.station_terminals.rows().size())fail("OrphanMilitaryDutySource");});}
